import{_ as s,l as r,o as e,c as i,v as n,p as l,x as t,d as h,i as c,S as u}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"机器学习与因果","description":"","frontmatter":{"title":"机器学习与因果","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ml-causal-econ.md","filePath":"econ/ml-causal-econ.md","lastUpdated":1789023840000}'),E={name:"econ/ml-causal-econ.md"};function d(m,a,p,A,B,_){const o=r("Mermaid");return e(),i("div",null,[a[1]||(a[1]=n('<h1 id="机器学习与因果" tabindex="-1">机器学习与因果 <a class="header-anchor" href="#机器学习与因果" aria-label="Permalink to &quot;机器学习与因果&quot;">​</a></h1><div class="epigraph"><p>预测好不等于处理效应对；用交叉拟合把 nuisance 估准，正交化之后，ATE 的推断才能回到 $\\sqrt{n}$，而不被随机森林的正则偏误拖死。</p><footer>—— Chernozhukov et al., Double/Debiased Machine Learning, Econometrics Journal 2018；Athey and Imbens 机器学习与因果综述；Belloni, Chernozhukov and Hansen 高维选择</footer></div><p><a href="/econ/inference-robust-cluster">上一课</a>把三明治与聚类钉在低维回归上。本课缺口是高维 \\(X\\)、灵活 nuisance：机器学习进因果。计量课程到此结束；下一课程宏观核算从 <a href="/econ/gdp-accounts">GDP</a> 起。不把本课写成大模型栏的 Transformer，也不写限价簿预测竞赛。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>条件平均 \\(\\mathbb{E}[Y\\mid D,X]\\) 与倾向 \\(e(X)\\) 可以很弯曲，\\(X\\) 可以几百个。逐步回归、事后挑选显著控制，会把选择噪声喂进 \\(\\hat\\beta\\)，标准误太小（Leeb–Pötscher）。Belloni–Chernozhukov–Hansen：对结果方程与处理方程分别做惩罚选择，再把并集放进回归（post-double-selection），在稀疏下恢复 \\(\\sqrt{n}\\)。Chernozhukov 等的 DML：交叉拟合估 \\(\\hat m(X)\\)、\\(\\hat e(X)\\)，用 Neyman 正交得分估 ATE / LATE，使 nuisance 的一阶误差消掉。缺口是：CIA 或 IV 排除<strong>仍然要</strong>，ML 只处理 nuisance 的函数形式，不创造外生。</p><p><span class="marginnote">Athey–Wager 因果森林：估 \\(\\mathbb{E}[\\tau\\mid X=x]\\) 的异质。诚实分割（样本切成切树与估叶）避免用同一数据既找分割又报效应。这是条件效应，不是新的 ATE 定义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>DML 步骤：样本切 \\(K\\) 折；在补集上训 \\(\\hat e,\\hat m\\)；在折内算正交化残差 \\(\\hat u=Y-\\hat m(X)\\)、\\(\\hat v=D-\\hat e(X)\\)，回归 \\(\\hat u\\) 对 \\(\\hat v\\)（或部分线性、IV 版本）。报告对折数、算法（lasso、随机森林、boosting）的敏感。高维 IV：对第一阶段与结果的控制同样正交化，弱工具诊断还在。</p>',8)),(e(),l(u,null,{default:t(()=>[c(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CIA%5B%22%E8%AF%86%E5%88%AB%E5%81%87%E8%AE%BE%E4%BB%8D%E8%A6%81%22%5D%20--%3E%20NU%5B%22nuisance%3A%20e(X)%2C%20m(X)%22%5D%0A%20%20NU%20--%3E%20ML%5B%22%E7%81%B5%E6%B4%BB%20ML%20%2B%20%E4%BA%A4%E5%8F%89%E6%8B%9F%E5%90%88%22%5D%0A%20%20ML%20--%3E%20ORTH%5B%22%E6%AD%A3%E4%BA%A4%E5%BE%97%E5%88%86%22%5D%0A%20%20ORTH%20--%3E%20ATE%5B%22%E2%88%9An%20%E6%8E%A8%E6%96%AD%22%5D%0A%20%20PICK%5B%22%E4%BA%8B%E5%90%8E%E6%8C%91%E9%80%89%E6%8E%A7%E5%88%B6%22%5D%20--%3E%20BAD%5B%22%E5%90%8D%E4%B9%89%20SE%20%E8%BF%87%E5%B0%8F%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n('<p>预测竞赛（哪只股票下周涨）优化的是 \\(\\mathbb{E}[Y\\mid X]\\)，可以把 \\(D\\) 当普通特征；因果禁止把中介、碰撞当 \\(X\\)，也禁止用处理后再测变量。目标函数不同。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是正交：ATE 的得分对 nuisance 的一阶扰动导数为零，于是 \\(\\hat e\\) 收敛得比 \\(n^{-1/4}\\) 快就够，不必 \\(n^{-1/2}\\)。交叉拟合切断「用同一观测既拟合 nuisance 又估目标」的过拟合。没有正交，lasso 的正则偏误会污染 \\(\\hat\\tau\\) 的中心极限。</p><p>与<a href="/econ/heterogeneous-effects">异质处理效应</a>：因果森林给出 \\(\\hat\\tau(x)\\)，加总方式仍要声明（对处理分布还是对目标政策分布）。与<a href="/econ/lucas-critique">卢卡斯批判</a>：更好的预测方程在规则改变时同样可以垮；DML 不是结构。</p><p><span class="marginnote">本栏不写注意力头、不写 token。机器学习在这里是 nuisance 估计器的统称。大模型栏的训练目标是下一个 token，与 ATE 正交得分不是同一对象。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不保证随机森林在你的 \\(N=300\\) 州面板上优于线性。重叠仍要：\\(\\hat e\\) 贴 0 或 1 时 IPW 爆炸，ML 可以把预测做得更贴，从而更危险。下一单元结构模型问的是均衡与反事实政策，不是更灵活的 CIA。拍卖、离散选择有自己的似然，不要默认 DML 替代。</p><p>后课默认：高维控制用双选择或 DML，不要逐步回归；识别假设单独写。预测优不等于因果对。下一课结构对约化：Lucas 的句子在灵活 nuisance 之后仍然成立。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ML 估 nuisance，不创造外生；CIA / IV 仍要。</li><li>正交 + 交叉拟合让 ATE 回到 \\(\\sqrt{n}\\)。</li><li>事后挑选控制会低估标准误。</li><li>因果森林给 \\(\\tau(x)\\)，加总规则仍要声明。</li><li>出处：Belloni, Chernozhukov and Hansen；Chernozhukov et al., <em>Econometrics Journal</em> 2018；Athey and Imbens；Wager and Athey。</li></ul>',10))])}const D=s(E,[["render",d]]);export{f as __pageData,D as default};
